import{r as e}from"./rolldown-runtime-BJX4KsWX.js";import{$a as t,$n as n,At as r,Bi as i,Br as a,Cr as o,Ct as s,Dr as c,Gr as l,Hi as u,Hr as d,Ja as f,Ji as p,Jr as m,Lt as h,Mi as g,Nt as _,Or as v,Ot as y,Pt as b,Qa as x,Rt as S,Sr as ee,St as te,Ti as ne,Tn as re,Un as C,Vi as ie,Wn as ae,Xi as oe,Xr as se,Ya as w,Yn as T,_t as ce,ao as le,bt as ue,co as de,cr as fe,eo as pe,er as me,fo as he,ga as ge,gt as E,ht as _e,ii as ve,io as ye,ir as be,ji as xe,jt as D,kr as Se,kt as Ce,no as O,nr as we,or as Te,qa as Ee,qi as De,rr as Oe,va as ke,vr as Ae,vt as je,xi as Me,xt as k,zi as Ne}from"./three.module-BHgkUel4.js";import{r as Pe}from"./slalom-catalog-B1XTcAdv.js";import{S as Fe,T as Ie,d as Le,p as Re,r as ze,w as Be}from"./activityHomes-E-L1DMaJ.js";import{n as Ve}from"./moonGolfRoster-B_N8FzGw.js";import{l as He,t as A}from"./pressure-BPoAU-a-.js";import{N as Ue,P as We,_ as Ge,b as Ke,j as qe,v as Je,w as Ye,x as j,y as Xe}from"./recordsExplorer-7UjCEvRU.js";import{i as Ze}from"./recordsTable-CnKmJ22v.js";var Qe={haze:{title:`Clouds made of another kind of ice`,question:`What are the bright clouds made of?`,finding:`A high-altitude cloud sample and its flight readings are aboard.`,science:`Voyager 2 saw bright, cirrus-like clouds on Neptune. In that frigid atmosphere, those clouds are made of frozen methane rather than the water-ice crystals in Earth’s cirrus clouds.`,connection:`You climbed into the thin upper haze to reach this station. Below you, the brighter methane cloud layer marks another part of the survey.`,source:`NASA · Neptune’s Clouds`,url:`https://science.nasa.gov/photojournal/neptunes-clouds/`},jet:{title:`A world that moves sideways`,question:`How powerful can this wind become?`,finding:`A jet-stream sample and its local wind reading are aboard.`,science:`Neptune’s winds can exceed 2,000 km/h, carrying frozen-methane clouds across the planet. Its large dark storms also change over time; the Great Dark Spot seen in 1989 later disappeared.`,connection:`In this flight, the jet layer brings frequent, sharp bursts. The reading below records the game’s wind at docking, not Neptune’s maximum wind speed.`,source:`NASA · Neptune Facts`,url:`https://science.nasa.gov/neptune/neptune-facts/`},deep:{title:`Deeper does not mean ground`,question:`What is beneath these clouds?`,finding:`A deep-cloud sample and its pressure reading are aboard.`,science:`Neptune has no solid surface to land on. Its atmosphere extends downward into a dense interior. Experiments exploring possible diamond formation concern extreme conditions deep inside ice giants.`,connection:`Your drone is still in atmosphere. This survey’s pressure scale is compressed for play, and its diamond-shaped rain crystals are fictional collectibles.`,source:`SLAC · Diamond-rain research`,url:`https://www6.slac.stanford.edu/news/2024-01-08-diamond-rain-icy-planets-offers-clues-magnetic-field-mysteries`}},M={name:`Nāhuku Lava Tube`,lat:19.41359,lon:-155.238811,source:`https://www.nps.gov/havo/planyourvisit/parking.htm`,description:`Three authored caves inspired by Kīlauea lava tubes.`},$e={jezero:[{mode:`tour`,name:`Perseverance Expedition`,activity:`guided-tour`,ready:!0,scored:!1,description:`Follow Perseverance’s journey through historical checkpoint stops.`},{mode:`roam`,name:`Free Roam`,activity:`roam`,ready:!0,scored:!1,description:`Explore Jezero freely by rover.`}],gale:[{mode:`tour`,name:`Curiosity Expedition`,activity:`guided-tour`,ready:!0,scored:!1,description:`Follow Curiosity from its landing basin into Mount Sharp.`},{mode:`roam`,name:`Free Roam`,activity:`explore`,ready:!0,scored:!1,description:`Explore Mount Sharp freely by rover.`}]},et={jezero:[],gale:[]};function N(e){return e===`jezero`||e===`gale`}function tt(e){return[...$e[e],...et[e]].filter(e=>e.ready)}function nt(e){return $e[e].filter(e=>e.ready)}function rt(e){return[...tt(e).flatMap(e=>[{id:e.activity,name:e.name},...(e.children??[]).map(e=>({id:e.activity,name:e.name}))])]}functio